import{_ as e,c as t,o as a,a4 as r}from"./chunks/framework.DzOtv0XR.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"server/server-sent-events.md","filePath":"server/server-sent-events.md"}'),s={name:"server/server-sent-events.md"},o=r('<p>Server-sent events (SSE) 是一种实现服务器向客户端推送事件的 Web 技术。它允许服务器推送数据到客户端，而不需要客户端进行轮询请求。SSE 主要用于以下几种场景：</p><ol><li><p>实时数据更新：SSE 可以实现实时的数据更新，例如股票价格、天气预报、实时聊天等。服务器可以将数据推送到客户端，而无需客户端不停地发送请求。</p></li><li><p>通知和提醒：SSE 可以用于发送通知和提醒，例如新邮件通知、社交媒体消息通知等。</p></li><li><p>日志和监控：SSE 可以用于实时监控和记录系统日志、服务器状态等。</p></li><li><p>多人协作：SSE 可以用于多人协作的应用，例如在线文本编辑器、协同白板等。</p></li></ol><p>总的来说，SSE 可以用于任何需要实时推送数据的场景，可以提高 Web 应用程序的效率和性能，并减少网络带宽的占用。</p><h2 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h2><p><strong>单向通信、有状态连接</strong></p><p>虽然 Server-sent events（SSE）有很多优点，但也存在一些缺点，包括：</p><ol><li><p>兼容性问题：虽然 SSE 是一种 HTML5 规范，但并不是所有浏览器都支持它。特别是在旧版的浏览器上可能会有问题（IE 不支持），需要使用 Polyfill 来解决兼容性问题。</p></li><li><p>可靠性问题：在 SSE 中，客户端和服务器之间的连接是长期保持的，如果连接断开，则需要重新建立连接。如果服务器在中途崩溃或重启，则客户端将无法接收到新的数据，直到重新建立连接。</p></li><li><p>有状态连接：SSE 的连接是有状态的，这意味着服务器需要在内存中维护每个客户端的连接状态。如果同时有大量客户端连接，则可能会对服务器的性能和内存使用造成影响。</p></li><li><p>单向通信：SSE 只支持服务器向客户端发送数据，客户端无法向服务器发送数据。如果需要进行双向通信，则需要使用其他技术，如 WebSocket。</p></li></ol><h2 id="用例" tabindex="-1">用例 <a class="header-anchor" href="#用例" aria-label="Permalink to &quot;用例&quot;">​</a></h2><p>Server-sent events（SSE）是一种基于Web的技术，已经被广泛应用于各种领域。以下是一些知名公司或项目在使用SSE的示例：</p><ol><li><p>Github: Github 使用 SSE 来向用户发送实时通知，例如代码合并请求、新问题等。</p></li><li><p>Facebook: Facebook 使用 SSE 来向用户发送实时通知，例如新消息、新朋友请求等。</p></li><li><p>Slack: Slack 使用 SSE 来实现实时聊天功能，使用户可以在不刷新页面的情况下接收和发送消息。</p></li><li><p>Google Drive: Google Drive 使用 SSE 来提供实时协作功能，例如多人编辑和评论文档等。</p></li><li><p>Financial Times: Financial Times 使用 SSE 来提供实时新闻更新，使用户可以在网站上获取最新的新闻和事件。</p></li></ol><p>除了上述公司和项目，还有许多其他的公司和项目正在使用SSE来实现实时通知、协作、监控和日志记录等功能。因此，SSE 是一个非常有用的Web技术，在许多不同的应用场景中都得到了广泛的应用。</p><h2 id="demo" tabindex="-1">DEMO <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;DEMO&quot;">​</a></h2><p><a href="https://github.com/cyio/sse-tutorial" target="_blank" rel="noreferrer">https://github.com/cyio/sse-tutorial</a></p><p><a href="https://juejin.cn/post/7205412097953808445" target="_blank" rel="noreferrer">实时通信变得简单——使用Node.js和Server-sent events的完整教程 - 掘金</a></p><p>SSE 封装 <a href="https://github.com/yetone/openai-translator/blob/63e0564679d9dbad37e187aa9b995304337728ce/src/content_script/utils.ts#L69" target="_blank" rel="noreferrer">https://github.com/yetone/openai-translator/blob/63e0564679d9dbad37e187aa9b995304337728ce/src/content_script/utils.ts#L69</a></p><h2 id="event-stream" tabindex="-1">Event Stream <a class="header-anchor" href="#event-stream" aria-label="Permalink to &quot;Event Stream&quot;">​</a></h2><p>WebSockets或Server-Sent Events（SSE）</p><p>chrome dev tools apparently only works with the native EventSource</p><h2 id="stream-fetch" tabindex="-1">stream fetch <a class="header-anchor" href="#stream-fetch" aria-label="Permalink to &quot;stream fetch&quot;">​</a></h2><p>chromium105+</p><p><a href="https://glitch.com/~fetch-request-stream" target="_blank" rel="noreferrer">https://glitch.com/~fetch-request-stream</a><a href="https://developer.chrome.com/articles/fetch-streaming-requests/#streaming-request-bodies" target="_blank" rel="noreferrer">Streaming requests with the fetch API - Chrome Developers</a></p><p><a href="https://www.youtube.com/watch?v=o1yKuH86_So" target="_blank" rel="noreferrer">Consume Web streams from OpenAI using vanilla JavaScript - NO DEPENDENCIES! - YouTube</a><a href="https://umaar.com/dev-tips/269-web-streams-openai/" target="_blank" rel="noreferrer">https://umaar.com/dev-tips/269-web-streams-openai/</a></p><h2 id="http-streaming-transfer-encoding-chunked" tabindex="-1">HTTP Streaming (Transfer-Encoding: chunked) <a class="header-anchor" href="#http-streaming-transfer-encoding-chunked" aria-label="Permalink to &quot;HTTP Streaming (Transfer-Encoding: chunked)&quot;">​</a></h2><p>更通用，支持任意数据格式，而 SSE 只支持文本</p><h2 id="与-ws-对比" tabindex="-1">与 WS 对比 <a class="header-anchor" href="#与-ws-对比" aria-label="Permalink to &quot;与 WS 对比&quot;">​</a></h2><ul><li>是否保持长连接，可扩展性，成本</li></ul><h2 id="模拟-ws" tabindex="-1">模拟 WS <a class="header-anchor" href="#模拟-ws" aria-label="Permalink to &quot;模拟 WS&quot;">​</a></h2><ul><li>模拟：把历史输入都带上</li></ul>',28),n=[o];function i(l,h,p,c,S,m){return a(),t("div",null,n)}const b=e(s,[["render",i]]);export{u as __pageData,b as default};
